CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON user_sessions(expires_at);
CREATE TABLE user_settings(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE watchlists(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE watchlist_items(id uuid PRIMARY KEY, watchlist_id uuid NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, asset_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(watchlist_id,asset_key));
CREATE TABLE data_sources(id text PRIMARY KEY, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, connector_type text NOT NULL DEFAULT 'pull', mode text NOT NULL CHECK(mode IN ('fixture','live')), interval_seconds integer NOT NULL DEFAULT 60 CHECK(interval_seconds>=10), last_success_at timestamptz, last_error text, next_poll_at timestamptz, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_checkpoints(source_id text PRIMARY KEY REFERENCES data_sources(id), cursor jsonb NOT NULL, committed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_health_records(id uuid PRIMARY KEY, source_id text NOT NULL REFERENCES data_sources(id), status text NOT NULL, latency_ms integer, error text, observed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX source_health_time ON source_health_records(source_id,observed_at DESC);
CREATE TABLE ingestion_runs(id uuid PRIMARY KEY, source_id text NOT NULL REFERENCES data_sources(id), status text NOT NULL, fetched integer NOT NULL DEFAULT 0, inserted integer NOT NULL DEFAULT 0, error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE raw_items(id uuid PRIMARY KEY, source_id text NOT NULL REFERENCES data_sources(id), external_id text NOT NULL, payload jsonb NOT NULL, published_at timestamptz, first_seen_at timestamptz NOT NULL, collected_at timestamptz NOT NULL, UNIQUE(source_id,external_id));
CREATE TABLE events(id uuid PRIMARY KEY, fingerprint text NOT NULL UNIQUE, source_id text NOT NULL REFERENCES data_sources(id), external_id text NOT NULL, title text NOT NULL, event_type text NOT NULL, severity text NOT NULL CHECK(severity IN ('P0','P1','P2','P3')), first_seen_at timestamptz NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_seen ON events(first_seen_at DESC);
CREATE INDEX events_severity_seen ON events(severity,first_seen_at DESC);
CREATE INDEX events_data_gin ON events USING gin(data jsonb_path_ops);
CREATE TABLE event_sources(id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id), source_id text NOT NULL REFERENCES data_sources(id), raw_item_id uuid NOT NULL REFERENCES raw_items(id), url text, source_published_at timestamptz, data jsonb NOT NULL DEFAULT '{}', UNIQUE(event_id,raw_item_id));
CREATE TABLE projects(id uuid PRIMARY KEY, asset_key text NOT NULL UNIQUE, stage text NOT NULL, chain text NOT NULL, first_seen_at timestamptz NOT NULL, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_seen ON projects(first_seen_at DESC);
CREATE TABLE project_lifecycle_events(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), from_stage text, to_stage text NOT NULL, reason text NOT NULL, evidence_ids jsonb NOT NULL DEFAULT '[]', occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_metrics(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), source_id text NOT NULL REFERENCES data_sources(id), observed_at timestamptz NOT NULL, data jsonb NOT NULL, UNIQUE(project_id,source_id,observed_at));
CREATE TABLE opportunity_signals(id uuid PRIMARY KEY, dedup_key text NOT NULL UNIQUE, project_id uuid REFERENCES projects(id), event_id uuid REFERENCES events(id), detected_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX signals_detected ON opportunity_signals(detected_at DESC);
CREATE TABLE risk_assessments(id uuid PRIMARY KEY, project_id uuid REFERENCES projects(id), event_id uuid REFERENCES events(id), score integer NOT NULL CHECK(score>=0 AND score<=100), version text NOT NULL, data jsonb NOT NULL, assessed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alert_rules(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alert_rule_versions(id uuid PRIMARY KEY, rule_id uuid NOT NULL REFERENCES alert_rules(id), version integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rule_id,version));
CREATE TABLE alert_triggers(id uuid PRIMARY KEY, rule_id uuid NOT NULL REFERENCES alert_rules(id), rule_version integer NOT NULL, event_id uuid REFERENCES events(id), signal_id uuid REFERENCES opportunity_signals(id), dedup_key text NOT NULL UNIQUE, data jsonb NOT NULL, detected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_channels(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,provider));
CREATE TABLE notifications(id uuid PRIMARY KEY, dedup_key text NOT NULL UNIQUE, channel_id uuid NOT NULL REFERENCES notification_channels(id), event_id uuid REFERENCES events(id), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENDING','SENT','FAILED','RETRYING','CANCELLED')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), queued_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, locked_until timestamptz, last_error text, data jsonb NOT NULL);
CREATE INDEX notifications_pending ON notifications(status,next_attempt_at);
CREATE TABLE notification_attempts(id uuid PRIMARY KEY, notification_id uuid NOT NULL REFERENCES notifications(id), attempt_no integer NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, outcome text NOT NULL, platform_message_id text, error text, data jsonb NOT NULL DEFAULT '{}', UNIQUE(notification_id,attempt_no));
CREATE TABLE ai_analysis_runs(id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), status text NOT NULL, provider text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, cache_key text NOT NULL UNIQUE, input_tokens integer, output_tokens integer, estimated_cost numeric(14,8), data jsonb NOT NULL DEFAULT '{}', error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX ai_runs_created ON ai_analysis_runs(created_at);
CREATE TABLE audit_logs(id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text, request_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_settings(key text PRIMARY KEY, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE market_observations(id uuid PRIMARY KEY, asset_key text NOT NULL, source_id text NOT NULL REFERENCES data_sources(id), observed_at timestamptz NOT NULL, value numeric(30,10) NOT NULL, unit text NOT NULL, delay_seconds integer, data jsonb NOT NULL DEFAULT '{}', UNIQUE(asset_key,source_id,observed_at));
CREATE INDEX markets_time ON market_observations(asset_key,observed_at DESC);
CREATE TABLE outbox_jobs(id uuid PRIMARY KEY, dedup_key text NOT NULL UNIQUE, kind text NOT NULL, entity_id uuid NOT NULL, status text NOT NULL DEFAULT 'PENDING', available_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox_jobs(status,available_at);
